ribbon_motion:
export function ribbonLight(node: SVGGElement, route: { path: string; from: number; to: number }) {
  const motion = matchMedia('(prefers-reduced-motion: reduce)');
  let animation: Animation | undefined;
  let stopped = false;
  node.style.offsetPath = `path('${route.path}')`;
  node.dataset.from = String(route.from); node.dataset.to = String(route.to);
  node.style.offsetRotate = 'auto';
  const run = () => {
    if (stopped || motion.matches) return;
    if (animation) { animation.onfinish = null; animation.cancel(); }
    const duration = randomBetween(7000, 15000);
    node.dataset.duration = String(Math.round(duration));
    const fade = 3000 / duration;
    const distanceAt = (offset: number) => `${route.from + (route.to - route.from) * offset}%`;
    animation = node.animate([
      { offset: 0, offsetDistance: distanceAt(0), opacity: 0 },
      { offset: fade, offsetDistance: distanceAt(fade), opacity: 1 },
      { offset: 1 - fade, offsetDistance: distanceAt(1 - fade), opacity: 1 },
      { offset: 1, offsetDistance: distanceAt(1), opacity: 0 },
    ], { duration, easing: 'linear', fill: 'forwards' });
    animation.onfinish = run;
    if (document.hidden) animation.pause();
  };
  const visibility = () => { if (document.hidden) animation?.pause(); else if (!motion.matches) animation?.play(); };
  const preference = () => {
    if (animation) { animation.onfinish = null; animation.cancel(); }
    node.style.offsetDistance = `${(route.from + route.to) / 2}%`;
    if (!motion.matches) run();
  };
  preference();
  motion.addEventListener('change', preference);
  document.addEventListener('visibilitychange', visibility);
  return { destroy() {
    stopped = true;
    if (animation) { animation.onfinish = null; animation.cancel(); }
    motion.removeEventListener('change', preference);
    document.removeEventListener('visibilitychange', visibility);
  } };
}

hatch:
function startReveal() {
  holdEgg = false;
  if (phase === 'egg') {
    // These cinematic timings are deliberately slower than a UI control.
    later(() => phase = reduced ? 'reveal' : 'shake', 1400);
    if (reduced) later(finishReveal, 1850);
    else {
      later(() => phase = 'bloom', 2050);
      later(() => phase = 'reveal', 3970); // 1800ms expansion, then 120ms fully white
      later(finishReveal, 5970); // the white layer fades for exactly 2000ms
    }
  }
}

egg_styles:
.egg-scene { position:absolute; inset:0; opacity:1; transition:opacity 250ms ease; }
.egg-art { position:absolute; top:50%; left:62%; height:116%; aspect-ratio:1; transform:translate(-49.8%,-51.4%); }
.egg-art img { display:block; width:100%; height:100%; object-fit:contain; transform:rotate(0); }
.egg-floor { position:absolute; left:62%; width:52%; height:8%; transform:translateX(-50%); border-radius:50%; bottom:0; background:#f58ace55; filter:blur(.7cqw); }
.egg-scene.shaking img { animation:egg-awake 2450ms ease-in-out both; }
.egg-scene.gone { opacity:0; }
.reveal-clip { position:absolute; inset:0; overflow:hidden; border-radius:inherit; pointer-events:none; z-index:4; }
.bloom { position:absolute; left:62%; top:50%; width:var(--bloom-diameter); aspect-ratio:1; border-radius:50%; background:radial-gradient(circle closest-side,#fff 0%,#fff var(--bloom-core),#fff0 100%); opacity:0; transform:translate(-50%,-50%) scale(.025); transition:transform 1800ms cubic-bezier(.23,1,.32,1),opacity 250ms ease; }
.bloom.expanding { transform:translate(-50%,-50%) scale(1); opacity:1; }
.bloom.fading { transform:translate(-50%,-50%) scale(1); opacity:0; transition:opacity 2000ms linear; }
